package com.franco.desco.adapter.in.web.delivery;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.delivery.*;import com.franco.desco.application.delivery.port.in.DeliveryUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController@RequestMapping("/api/v1/entregas")@Tag(name="Acopio y entregas",description="Registro, valorización, confirmación y anulación de entregas de socios.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class DeliveryController{private final DeliveryUseCase u;private final DeliveryWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public DeliveryController(DeliveryUseCase u,DeliveryWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'ENTREGAS_LISTAR')")@Operation(operationId="entregasListar",summary="Listar entregas")public ResponseEntity<ApiResponse<PageResponse<DeliveryResponses.Summary>>>list(@RequestParam(required=false)Long operativoVentaId,@RequestParam(required=false)Long socioId,@RequestParam(required=false)String estadoProceso,@RequestParam(required=false)String estadoControlCalidad,@RequestParam(required=false)LocalDate fechaDesde,@RequestParam(required=false)LocalDate fechaHasta,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,operativoVentaId,socioId,estadoProceso,estadoControlCalidad,fechaDesde,fechaHasta),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}")@PreAuthorize("@permissionGuard.has(authentication,'ENTREGAS_VER')")@Operation(operationId="entregasVer",summary="Ver detalle y valorización de entrega")public ResponseEntity<ApiResponse<DeliveryResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new DeliveryCommands.Get(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'ENTREGAS_CREAR')")@Operation(operationId="entregasCrear",summary="Registrar entrega",description="Precios, peso neto, peso aceptado e importes son validados/calculados por el PA.")public ResponseEntity<ApiResponse<DeliveryResponses.Created>>create(@Valid@RequestBody DeliveryRequests.Create q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.create(new DeliveryCommands.Create(q.operativoSocioId(),q.predioId(),q.codigoLote(),q.fechaHora(),q.pesoBrutoKg(),q.taraKg(),q.pesoRechazadoKg(),q.estadoControlCalidad(),q.ticketBalanza(),q.observacion(),map.lines(q.detalles())),ids.resolve(a),meta.resolve(r)),r,DeliveryResponses.Created::new);}
 @PutMapping("/{id}/preliminar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'ENTREGAS_EDITAR')")@Operation(operationId="entregasEditarPreliminar",summary="Editar entrega preliminar")public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody DeliveryRequests.UpdatePreliminary q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.updatePreliminary(new DeliveryCommands.UpdatePreliminary(id,q.pesoBrutoKg(),q.taraKg(),q.pesoRechazadoKg(),q.estadoControlCalidad(),q.ticketBalanza(),q.observacion(),map.lines(q.detalles())),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/confirmar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'ENTREGAS_CONFIRMAR')")@Operation(operationId="entregasConfirmar",summary="Confirmar entrega")public ResponseEntity<ApiResponse<Void>>confirm(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.confirm(new DeliveryCommands.Confirm(id),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/anular")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'ENTREGAS_RETIRAR')")@Operation(operationId="entregasAnular",summary="Anular entrega")public ResponseEntity<ApiResponse<Void>>annul(@PathVariable Long id,@Valid@RequestBody DeliveryRequests.Annul q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.annul(new DeliveryCommands.Annul(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}}
